namespace mod_mootimeter\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use mod_mootimeter\local\exporter;
use mod_mootimeter\local\external_util;

/**
 * Web service returning the page list of a mootimeter instance.
 *
 * @package     mod_mootimeter
 * @copyright   2026 ISB Bayern
 * @author      Dr. Peter Mayer
 * @license     https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
class get_pages extends external_api {
    /**
     * Describes the parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'cmid' => new external_value(PARAM_INT, 'Course module id'),
        ]);
    }

    /**
     * Return the pages visible for the current user and, for moderators, the tools that can be added.
     *
     * @param int $cmid
     * @return array
     */
    public static function execute(int $cmid): array {
        ['cmid' => $cmid] = self::validate_parameters(self::execute_parameters(), ['cmid' => $cmid]);
        [$cm, $context, $ismoderator] = external_util::validate_cm($cmid);

        return [
            'pages' => exporter::export_pages($cm, $context),
            'tools' => $ismoderator ? exporter::export_tools() : [],
        ];
    }

    /**
     * Describes the return structure.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return exporter::pages_structure();
    }
}
